var c=new LabPttController { MaxHoldMs=100 };
c.Press(0); c.Ready(c.Epoch,10);
c.Tick(99); Console.WriteLine(c.State); // Tx
c.Tick(100); Console.WriteLine(c.State); // Fault
Console.WriteLine(c.Press(110)); // False
c.Release(120); Console.WriteLine(c.Press(130)); // True

var c=new LabPttController(); c.Press(0); int old=c.Epoch;
c.Release(10); // 模擬本地撤銷，非證明遠端停止
c.Press(20); c.Ready(old,30);
Console.WriteLine(c.AudioOpen); // False
c.Ready(c.Epoch,40); Console.WriteLine(c.AudioOpen); // True
